//
// Heinzel S1/S2 scaling and the dBFS axis — the TypeScript side of ADR 0006
// D2 and D3, transcribed from `host/src/spectral_host/spectrum.py`.
//
//   S1    = Σ w[j]                 S2 = Σ w[j]²         NENBW = N·S2/S1²  [bins]
//   PS  [FS²]    = 2·|X[k]|² / S1²          ENBW  = NENBW · fs/N   [Hz]
//   PSD [FS²/Hz] = 2·|X[k]|² / (fs·S2)      PS = PSD · ENBW
//   factor 2 on k = 1 … N/2−1 only; DC and Nyquist are NOT doubled
//   the injected transform is UNNORMALISED (no 1/N, no 1/√N)
//
// THE DELIBERATE DIVERGENCE FROM THE ANCHOR, repeated here because it is a
// 3.01 dB difference at exactly two bins: Heinzel eq. (23) is stated for
// m = 0 … N/2 and his text then waives the DC and Nyquist distinction
// ("we do, however, ignore this distinction"). ADR 0006 D2 does NOT ignore it.
// A reference implementation written from the paper verbatim disagrees with
// this file by 3.01 dB at bin 0 and bin N/2 and nowhere else, which is why
// `tests/unit/dc-and-nyquist-are-not-doubled.test.ts` exists as its own hazard.
//
// The schema enumerates more `normalization` × `scaling` pairs than ADR 0006
// ratifies, so a manifest can RECORD whatever convention a set was built with.
// `scale()` is therefore total over the enum; the ratified pair is
// (`S1`, `power_spectrum`) with (`S2`, `power_spectral_density`) as its density
// form, and the rest are recorded conventions, not ratified ones — each is
// marked below.
// ----------------------------------------------------------------------------

/** `manifest.schema.yaml` `analyses.spectrum.normalization`. */
export const NORMALIZATIONS = ['none', '1/N', '1/sqrt(N)', 'coherent_gain', 'S1', 'S2'] as const;
export type Normalization = (typeof NORMALIZATIONS)[number];

/** `manifest.schema.yaml` `analyses.spectrum.scaling`. */
export const SCALINGS = [
  'power_spectrum',
  'power_spectral_density',
  'linear_spectrum',
  'linear_spectral_density',
] as const;
export type Scaling = (typeof SCALINGS)[number];

/** `manifest.schema.yaml` `analyses.spectrum.dbfs_reference`. */
export const DBFS_REFERENCES = ['sine', 'square'] as const;
export type DbfsReference = (typeof DBFS_REFERENCES)[number];

/** `manifest.schema.yaml` `analyses.spectrum.int16_scale`. */
export const INT16_SCALES = [32768, 32767] as const;

/** `manifest.schema.yaml` `analyses.spectrum.dtype`. */
export const DTYPES = ['float32', 'float64'] as const;

/** The scalings that are per-Hz densities (Heinzel's PSD and LSD). */
export const DENSITY_SCALINGS: ReadonlySet<Scaling> = new Set<Scaling>([
  'power_spectral_density',
  'linear_spectral_density',
]);

/**
 * Reference power, in FS², of the signal that reads 0 dBFS (ADR 0006 D3 and the
 * schema's `dbfs_reference`): a full-scale sine has mean power A²/2 = 0.5; a
 * full-scale square has mean power 1.0, which puts the sine at −3.01 dBFS.
 */
export const REFERENCE_POWER: Readonly<Record<DbfsReference, number>> = Object.freeze({
  sine: 0.5,
  square: 1.0,
});

/** ADR 0006 D3: the display floor. */
export const DEFAULT_FLOOR_DB = -200;

/** ADR 0006 D3 / ADR 0003 d.2: the project's int16 seam. `32767` is admitted and differs by 0.00026 dB. */
export const DEFAULT_INT16_SCALE = 32768;

function assertOneOf<T extends string>(value: string, allowed: readonly T[], field: string): asserts value is T {
  if (!(allowed as readonly string[]).includes(value)) {
    throw new RangeError(`${field} must be one of ${allowed.join(', ')}, got ${JSON.stringify(value)}`);
  }
}

/**
 * `|X[k]|²` with the factor 2 on bins `1 … N/2−1` ONLY.
 *
 * DC (`k = 0`) and Nyquist (`k = N/2`) are NOT doubled: the two edge bins have
 * no mirror image in the two-sided spectrum, so doubling them overstates their
 * power by 3.01 dB (ADR 0006 D2).
 *
 * `spectrum` is `2·(N/2+1)` interleaved re/im as `RealFft.forward` writes it.
 */
export function oneSidedPower(spectrum: Float64Array, out?: Float64Array): Float64Array {
  if (spectrum.length < 4 || spectrum.length % 2 !== 0) {
    throw new RangeError(
      'a one-sided spectrum of an even transform has at least two bins (DC and Nyquist), interleaved re/im',
    );
  }
  const bins = spectrum.length / 2;
  const p = out ?? new Float64Array(bins);
  if (p.length < bins) {
    throw new RangeError(`out needs ${String(bins)} slots, got ${String(p.length)}`);
  }
  for (let k = 0; k < bins; k += 1) {
    const re = spectrum[2 * k] as number;
    const im = spectrum[2 * k + 1] as number;
    const power = re * re + im * im;
    p[k] = k === 0 || k === bins - 1 ? power : 2 * power;
  }
  return p;
}

/**
 * Turn an unnormalised one-sided power array into the quantity `scaling` names,
 * under `normalization`. The transcription of `spectrum.scale()`.
 *
 * Stage 1 — `normalization` fixes the divisor `D²` applied to the one-sided
 * power (DC/Nyquist already undoubled by `oneSidedPower`):
 *
 *     none → 1,  1/N → N²,  1/sqrt(N) → N,  coherent_gain → S1²,
 *     S1 → S1²,  S2 → S2.
 *
 * `S1` gives Heinzel's `PS = 2|X|²/S1²` directly; `S2` gives `fs·PSD = 2|X|²/S2`
 * directly. `coherent_gain` divides by `N·a₀`, which for a periodic cosine-sum
 * window IS `S1` (ADR 0006 D2 orthogonality), so it coincides with `S1` here —
 * the enum carries both because a manifest records the NAME a tool used, not
 * because they differ. `none`, `1/N` and `1/sqrt(N)` leave the window's gain in
 * the result (a tone reads `a₀²` low); they exist so a manifest can name an
 * uncalibrated convention. **NOT RATIFIED by ADR 0006** — those three are
 * recorded conventions and nothing in this application selects them.
 *
 * Stage 2 — `scaling` converts between the power spectrum and the density with
 * Heinzel's `PS = PSD·ENBW`, `ENBW = S2·fs/S1²` [Hz] (= `NENBW·fs/N`, the `N`
 * cancelling), and takes the square root for the linear forms. `linear_spectrum`
 * and `linear_spectral_density` are likewise **recorded, not ratified**: ADR
 * 0006 D8 forbids averaging or smoothing in an amplitude quantity, so nothing
 * in the live path may accumulate them.
 *
 * Units for an input scaled by `int16ToFloat`: FS² (PS), FS²/Hz (PSD), FS (LS),
 * FS/√Hz (LSD).
 */
export function scale(
  oneSided: Float64Array,
  s1: number,
  s2: number,
  fs: number,
  normalization: string,
  scaling: string,
  out?: Float64Array,
): Float64Array {
  assertOneOf(normalization, NORMALIZATIONS, 'normalization');
  assertOneOf(scaling, SCALINGS, 'scaling');
  if (!(s1 > 0) || !(s2 > 0) || !(fs > 0)) {
    throw new RangeError('S1, S2 and fs must be positive');
  }
  const bins = oneSided.length;
  const n = 2 * (bins - 1);
  const divisorSq: number = {
    none: 1,
    '1/N': n * n,
    '1/sqrt(N)': n,
    coherent_gain: s1 * s1,
    S1: s1 * s1,
    S2: s2,
  }[normalization];

  const enbw = (s2 * fs) / (s1 * s1);
  const result = out ?? new Float64Array(bins);
  if (result.length < bins) {
    throw new RangeError(`out needs ${String(bins)} slots, got ${String(result.length)}`);
  }
  for (let k = 0; k < bins; k += 1) {
    const p = (oneSided[k] as number) / divisorSq;
    // `S2` lands on fs·PSD, so PS is recovered through the exact ENBW identity;
    // every other normalisation lands on the PS axis and PSD is derived from it.
    const ps = normalization === 'S2' ? (p / fs) * enbw : p;
    const psd = normalization === 'S2' ? p / fs : p / enbw;
    let v: number;
    if (scaling === 'power_spectrum') {
      v = ps;
    } else if (scaling === 'power_spectral_density') {
      v = psd;
    } else if (scaling === 'linear_spectrum') {
      v = Math.sqrt(ps);
    } else {
      v = Math.sqrt(psd);
    }
    result[k] = v;
  }
  return result;
}

function dbOfRatio(ratio: number, floorDb: number): number {
  // Math.log10 in double, never a fast-log row: ADR 0006 D9 gives the device's
  // approximation its OWN 0.005 dB budget precisely so it may not eat the
  // 0.01 dB spectrum budget, and the browser has no cycle argument for one.
  const db = 10 * Math.log10(ratio);
  return db > floorDb ? db : floorDb;
}

/**
 * Level in dBFS — dB re the POWER of a full-scale sine (0.5 FS²) or square
 * (1.0 FS²): `10·log10(PS/ref)` (ADR 0006 D3).
 *
 * `v` is whatever `scaling` says it is. A spectrum (PS or its square root) is
 * converted directly; a DENSITY is first brought onto the PS axis with
 * Heinzel's `PS = PSD·ENBW`, which is why `enbwHz` is REQUIRED for the two
 * density scalings and REFUSED for the two spectrum scalings — passing it where
 * it does nothing is the "silently mixed" case D3 forbids. For the density axis
 * itself (dBFS/Hz) use `toDbfsPerHz`.
 *
 * Bins at or below `10^(floorDb/10)·ref` (exact zeros included) read `floorDb`;
 * D3's floor is −200 dB.
 */
export function toDbfs(
  v: Float64Array,
  dbfsReference: string,
  scaling: string,
  enbwHzValue?: number | null,
  floorDb: number = DEFAULT_FLOOR_DB,
  out?: Float64Array,
): Float64Array {
  assertOneOf(dbfsReference, DBFS_REFERENCES, 'dbfs_reference');
  assertOneOf(scaling, SCALINGS, 'scaling');
  const density = DENSITY_SCALINGS.has(scaling);
  if (density) {
    if (enbwHzValue === undefined || enbwHzValue === null || !(enbwHzValue > 0)) {
      throw new RangeError(`${scaling} is per Hz: toDbfs needs enbwHz > 0 to reach the PS axis (PS = PSD·ENBW)`);
    }
  } else if (enbwHzValue !== undefined && enbwHzValue !== null) {
    throw new RangeError(`${scaling} is not a density; enbwHz must be absent (ADR 0006 D3: axes are never mixed)`);
  }
  const ref = REFERENCE_POWER[dbfsReference];
  const result = out ?? new Float64Array(v.length);
  for (let k = 0; k < v.length; k += 1) {
    const value = v[k] as number;
    const linear = scaling === 'power_spectrum' || scaling === 'power_spectral_density' ? value : value * value;
    const ps = density ? linear * (enbwHzValue as number) : linear;
    result[k] = dbOfRatio(ps / ref, floorDb);
  }
  return result;
}

/**
 * The PSD display axis of ADR 0006 D3: `10·log10(PSD/ref)`, labelled dBFS/Hz.
 *
 * Density scalings only. A full-scale sine does NOT read 0 here — its peak bin
 * reads `10·log10(1/ENBW_Hz)` — which is the point: a different axis with a
 * different unit, never shown on the same readout as dBFS. Floor −200 dB.
 */
export function toDbfsPerHz(
  v: Float64Array,
  dbfsReference: string,
  scaling: string,
  floorDb: number = DEFAULT_FLOOR_DB,
  out?: Float64Array,
): Float64Array {
  assertOneOf(dbfsReference, DBFS_REFERENCES, 'dbfs_reference');
  assertOneOf(scaling, SCALINGS, 'scaling');
  if (!DENSITY_SCALINGS.has(scaling)) {
    throw new RangeError(`toDbfsPerHz is for the density scalings, got ${JSON.stringify(scaling)}`);
  }
  const ref = REFERENCE_POWER[dbfsReference];
  const result = out ?? new Float64Array(v.length);
  for (let k = 0; k < v.length; k += 1) {
    const value = v[k] as number;
    const psd = scaling === 'power_spectral_density' ? value : value * value;
    result[k] = dbOfRatio(psd / ref, floorDb);
  }
  return result;
}

/** Bin centre frequencies `k·fs/N` for `k = 0 … N/2` — `scipy.fft.rfftfreq(N, 1/fs)`. */
export function binFrequencies(fs: number, fftSize: number): Float64Array {
  if (!(fs > 0)) {
    throw new RangeError('fs must be positive');
  }
  if (!Number.isInteger(fftSize) || fftSize < 2 || fftSize % 2 !== 0) {
    throw new RangeError(`fft size must be an even integer >= 2, got ${String(fftSize)}`);
  }
  const bins = fftSize / 2 + 1;
  const f = new Float64Array(bins);
  for (let k = 0; k < bins; k += 1) {
    f[k] = (k * fs) / fftSize;
  }
  return f;
}
