//
// f0 by the McLeod Pitch Method — the NSDF, key maxima, and the first one
// that clears the bar.
//
// McLeod & Wyvill 2005, "A smarter way to find pitch" (bibliography 05 #8), the
// family ADR 0021 names for the browser estimator. Routing Q48 says this
// estimator MAY differ from the watch's (ADR 0020 is the watch's record, still
// in the backlog); both are compared to Praat, never to each other.
//
// THE NORMALISED SQUARE DIFFERENCE FUNCTION. For a lag τ over a window of W
// samples,
//
//     r'(τ) = Σ_{j=0}^{W−1−τ} x_j · x_{j+τ}                (autocorrelation)
//     m'(τ) = Σ_{j=0}^{W−1−τ} (x_j² + x_{j+τ}²)             (the energy of BOTH halves)
//     n'(τ) = 2·r'(τ) / m'(τ)                               (in [−1, 1])
//
// The division by m' is the whole point: a plain autocorrelation falls off
// with τ because fewer samples overlap, and its maximum drifts toward short
// lags; the NSDF is 1 at any lag where the signal exactly repeats, whatever the
// lag. That is also what makes "clarity" — the height of the chosen maximum —
// a level-independent voicing measure: a −60 dBFS sine and a 0 dBFS sine both
// score ≈ 1, and white noise scores ≈ 0.
//
// KEY MAXIMA, AND THE RULE THAT GUARDS THE OCTAVE. Skip the τ = 0 lobe to the
// first negative-going zero crossing; then take the maximum of every positive
// run. The pitch is the FIRST key maximum whose height is at least k times the
// highest of them — NOT the highest one. A periodic signal has maxima at τ, 2τ,
// 3τ … and with finite W the later ones can be marginally taller; picking the
// global maximum would read an octave (or more) low. k ∈ [0.8, 0.93] in the
// paper; 0.9 here `(prov.)`.
//
// WHY 32 ms AND NOT THE SPECTRUM'S 128 ms. Measured on the Praat pitch goldens
// before this file was written (numpy prototype, 2026-08-22, hop 10 ms):
// `vowel_a_vibrato_220_6hz_100c` — a ±100-cent vibrato at 6 Hz — reads a
// median residual of ≈ 1 cent against Praat at W = 1024, 12 cents at 2048 and
// 45 cents at 4096, where clarity collapses because the window is no longer
// self-similar across 0.77 vibrato cycles (VR 29 %). The other seven files sit
// under 0.1 cent at every W. The analytical model agrees: an averager of
// length T at 6 Hz keeps `sin(π·6T)/(π·6T)` of the depth — 0.94 / 0.78 / 0.28 —
// and Praat's own 46 ms Hann-tapered window reads 97 of the 100 cents. So the
// browser must average LESS than ≈ 42 ms to stay within 5 cents of the
// reference, and 32 ms is McLeod's own ratio W ≥ 2·τ_max for a 65 Hz floor.
// The TypeScript run in `tests/golden/f0-praat.test.ts` is the record; the
// prototype numbers above are why the constant is what it is, not evidence.
//
// WHAT A DC OFFSET DOES, MEASURED (2026-08-22, while writing the unit tests).
// It does NOT move the maxima: a constant contributes equally to r' and m', so
// a 220 Hz sine with +0.1 of offset reads 220.000 Hz either way. It lifts the
// FLOOR of n'(τ) toward dc² / (dc² + σ²) at every lag — but a floor that never
// crosses zero gives the key-maximum search nothing to find, so a pure offset
// over noise reads UNVOICED, blocker or not. The first draft of this header
// claimed the opposite (a confident false pitch); the test disproved it. The
// estimator reads the DC-blocked stream anyway, for consistency with
// 03-dsp-pipeline §9 and because it is the buffer the spectrum already has —
// not because this file could show it mattering. `tests/unit/mpm-nsdf.test.ts`
// pins both facts.
//
// DIRECT, NOT FFT. Σ_{τ ≤ 493} (1024 − τ) ≈ 0.38 M multiply-adds per hop,
// ≈ 19 M/s at 50 Hz — well under a millisecond in V8 against a 20 ms hop. An
// FFT route needs an inverse kernel this codebase does not have (`RealFft` is
// forward-only), a zero-padded 2048-point pair, and a rounding argument for
// r' near 1. The direct form is the paper's formula verbatim.
// ---------------------------------------------------------------------------

import { interpolatePeak } from '../worker/protocol';

export interface MpmParams {
  /** Lowest f0 the estimator will report, Hz. The golden manifest's `pitch_floor` (C2). */
  readonly floorHz: number;
  /** Highest f0, Hz. The manifest's `pitch_ceiling`. */
  readonly ceilingHz: number;
  /** Samples analysed per estimate — the NEWEST this many of what the caller hands over. `(prov.)` */
  readonly windowSamples: number;
  /** k: a key maximum is accepted if ≥ k · the highest key maximum. `(prov.)` */
  readonly keyMaxFraction: number;
  /** Below this clarity the frame is unvoiced. `(prov.)` */
  readonly clarityThreshold: number;
}

/** The analysis window, seconds. `(prov.)` — see the header for the measurement behind it. */
export const F0_WINDOW_S = 0.032;

/** The manifest's pitch band, Hz: `analyses.pitch.pitch_floor` / `pitch_ceiling`. */
export const F0_FLOOR_HZ = 65;
export const F0_CEILING_HZ = 1100;

export const KEY_MAX_FRACTION = 0.9;
export const CLARITY_THRESHOLD = 0.8;

export function defaultMpmParams(sampleRateHz: number): MpmParams {
  if (!(sampleRateHz > 0) || !Number.isFinite(sampleRateHz)) {
    throw new RangeError(`sample rate must be positive, got ${String(sampleRateHz)}`);
  }
  return Object.freeze({
    floorHz: F0_FLOOR_HZ,
    ceilingHz: F0_CEILING_HZ,
    windowSamples: Math.round(sampleRateHz * F0_WINDOW_S),
    keyMaxFraction: KEY_MAX_FRACTION,
    clarityThreshold: CLARITY_THRESHOLD,
  });
}

export interface LagRange {
  readonly minLag: number;
  readonly maxLag: number;
}

/**
 * Lags that map onto the pitch band, and the refusal that keeps the window
 * honest: two periods of the lowest f0 must fit, or the NSDF has no second
 * repetition to find at that lag (McLeod's W ≥ 2·τ_max).
 */
export function lagRange(params: MpmParams, sampleRateHz: number): LagRange {
  if (!(params.floorHz > 0) || !(params.ceilingHz > params.floorHz)) {
    throw new RangeError(`pitch band must satisfy 0 < floor < ceiling, got ${String(params.floorHz)}–${String(params.ceilingHz)} Hz`);
  }
  const minLag = Math.floor(sampleRateHz / params.ceilingHz);
  const maxLag = Math.floor(sampleRateHz / params.floorHz);
  if (minLag < 2) {
    throw new RangeError(`ceiling ${String(params.ceilingHz)} Hz is above what ${String(sampleRateHz)} Hz can resolve`);
  }
  if (params.windowSamples < 2 * maxLag + 2) {
    throw new RangeError(
      `a ${String(params.windowSamples)}-sample window cannot hold two periods of ${String(params.floorHz)} Hz at ` +
        `${String(sampleRateHz)} Hz (needs ≥ ${String(2 * maxLag + 2)})`,
    );
  }
  return { minLag, maxLag };
}

/**
 * n'(τ) for τ = 0 … maxLag + 1 (one past the range, so the last lag has a
 * right-hand neighbour to interpolate against). `out`, if given, must be at
 * least that long; it is returned.
 *
 * m'(τ) comes from a prefix sum of x² rather than a running subtraction, so
 * that nothing drifts across 500 lags.
 */
export function nsdf(x: ArrayLike<number>, maxLag: number, out?: Float64Array): Float64Array {
  const w = x.length;
  const lags = maxLag + 2;
  if (!Number.isInteger(maxLag) || maxLag < 1 || lags > w) {
    throw new RangeError(`maxLag ${String(maxLag)} is not usable with a ${String(w)}-sample window`);
  }
  const n = out ?? new Float64Array(lags);
  if (n.length < lags) {
    throw new RangeError(`scratch buffer of ${String(n.length)} is shorter than ${String(lags)} lags`);
  }

  // prefix[i] = Σ_{j<i} x_j²
  const prefix = new Float64Array(w + 1);
  let acc = 0;
  for (let j = 0; j < w; j += 1) {
    const v = x[j] as number;
    acc += v * v;
    prefix[j + 1] = acc;
  }

  for (let tau = 0; tau < lags; tau += 1) {
    const count = w - tau;
    let r = 0;
    for (let j = 0; j < count; j += 1) {
      r += (x[j] as number) * (x[j + tau] as number);
    }
    // m'(τ) = Σ_{j<count} x_j² + Σ_{j<count} x_{j+τ}²
    const m = (prefix[count] as number) + ((prefix[w] as number) - (prefix[tau] as number));
    n[tau] = m > 0 ? (2 * r) / m : 0;
  }
  return n;
}

export interface KeyMaximum {
  readonly lag: number;
  readonly value: number;
}

/**
 * McLeod's key maxima: the highest point of each positive run of n'(τ) after
 * the first negative-going zero crossing, restricted to `[minLag, maxLag]`.
 */
export function keyMaxima(n: ArrayLike<number>, minLag: number, maxLag: number): KeyMaximum[] {
  const out: KeyMaximum[] = [];
  let tau = 1;
  // Skip the τ = 0 lobe: it is 1 by definition and is not a period.
  while (tau <= maxLag && (n[tau] as number) > 0) {
    tau += 1;
  }
  while (tau <= maxLag) {
    // advance to the start of a positive run
    while (tau <= maxLag && (n[tau] as number) <= 0) {
      tau += 1;
    }
    if (tau > maxLag) {
      break;
    }
    let bestLag = -1;
    let best = -Infinity;
    while (tau <= maxLag && (n[tau] as number) > 0) {
      const v = n[tau] as number;
      if (tau >= minLag && v > best) {
        best = v;
        bestLag = tau;
      }
      tau += 1;
    }
    if (bestLag >= 0) {
      out.push({ lag: bestLag, value: best });
    }
  }
  return out;
}

export interface F0Estimate {
  /** Hz, or `null` when the frame is unvoiced (clarity below the threshold, or no key maximum). */
  readonly f0Hz: number | null;
  /** Height of the chosen NSDF maximum after interpolation, in [0, 1]; 0 when there was none. */
  readonly clarity: number;
  /** The refined lag in samples; 0 when there was none. */
  readonly lag: number;
}

/**
 * f0 of the NEWEST `params.windowSamples` of `samples`.
 *
 * The caller hands over whatever it has — the Worker hands the hop's whole
 * DC-blocked window — and this reads the tail, which is the freshest 32 ms
 * and the part furthest from the blocker's leading-edge transient.
 */
export function estimateF0(
  samples: Float32Array | Float64Array,
  sampleRateHz: number,
  params: MpmParams,
  scratch?: Float64Array,
): F0Estimate {
  const { minLag, maxLag } = lagRange(params, sampleRateHz);
  if (samples.length < params.windowSamples) {
    throw new RangeError(`estimateF0 needs ${String(params.windowSamples)} samples, got ${String(samples.length)}`);
  }
  const x = samples.subarray(samples.length - params.windowSamples);
  const n = nsdf(x, maxLag, scratch);
  const maxima = keyMaxima(n, minLag, maxLag);
  if (maxima.length === 0) {
    return { f0Hz: null, clarity: 0, lag: 0 };
  }
  let highest = -Infinity;
  for (const m of maxima) {
    if (m.value > highest) {
      highest = m.value;
    }
  }
  const bar = params.keyMaxFraction * highest;
  // The FIRST key maximum at or above the bar — the octave guard. Never the highest.
  const chosen = maxima.find((m) => m.value >= bar) as KeyMaximum;

  // Parabolic refinement on the three NSDF points around the chosen lag. The
  // existing interpolator's refusals (non-downward parabola, |d| > 1) are the
  // right semantics here too: a refusal leaves the integer lag.
  const triple = [n[chosen.lag - 1] as number, n[chosen.lag] as number, n[chosen.lag + 1] as number];
  const fit = interpolatePeak(triple, 1);
  const lag = chosen.lag + fit.deltaBins;
  const clarity = Math.min(1, fit.levelDb);
  return {
    f0Hz: clarity >= params.clarityThreshold ? sampleRateHz / lag : null,
    clarity,
    lag,
  };
}
